-- Editorially reconciled workflow overviews: concepts, decisions and handoffs, not duplicate procedures.
update public.rc_articles set title='Bookings: from request to settlement',summary='How this tool works, with contextual links to its detailed guidance.',body='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bookings helps WUWF evaluate a production request before accepting it: what the work requires, whether the station has capacity, and what the partner should pay. It then records delivery and actual cost. The "},{"type":"text","text":"Requests screen","marks":[{"type":"link","attrs":{"href":"/bookings/requests"}}]},{"type":"text","text":" is the starting point for an individual job."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cost and capacity are separate decisions"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"rate card","marks":[{"type":"link","attrs":{"href":"/bookings/rates/card"}}]},{"type":"text","text":" prices a defined scope of work using labor, equipment and other costs. University strategic or applied-learning work can receive a contribution of professional staff time where an eligible reserve is available; other university work and outside work receive their applicable rates. Being eligible for a contributed rate does not guarantee an available production window."}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Calendar","marks":[{"type":"link","attrs":{"href":"/bookings/calendar"}}]},{"type":"text","text":" accounts for labor, bookable resource pools, WUWF holds, reserved blocks and term capacity. Core obligations already excluded from available hours must not be counted again as holds. The airtime envelope shown in Bookings is a planning measure; actual announcements are placed in On Air or Traffic."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"From commitment to actuals"}]},{"type":"paragraph","content":[{"type":"text","text":"A request combines an estimate, feasibility checks and planned dates. A tentative hold is not final approval. Where a partner has an agreement, review it under "},{"type":"text","text":"Partners","marks":[{"type":"link","attrs":{"href":"/bookings/partners"}}]},{"type":"text","text":" and confirm whether the requested work and any reserved blocks fall within its terms. After delivery, production confirms resources used; Finance posts the settlement. Actual effort affects WUWF''s measured cost, but does not automatically change the amount quoted to the partner."}]},{"type":"paragraph","content":[{"type":"text","text":"Use the "},{"type":"text","text":"Term report","marks":[{"type":"link","attrs":{"href":"/bookings/report"}}]},{"type":"text","text":" to compare estimated work with settled results and inform future rate and capacity decisions. For specific buttons, stages and permissions, follow the detailed guides attached to each screen."}]}]}'::jsonb,version_note='Reconciled role-oriented overview; removed duplicate click-by-click instructions' where slug='bookings-workflow-overview' and kind='guide' and edited_since_release=false;
update public.rc_articles set title='Traffic: from signed order to fulfillment',summary='How this tool works, with contextual links to its detailed guidance.',body='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Traffic turns a signed underwriting order into an accountable broadcast obligation. Start with "},{"type":"text","text":"Contracts","marks":[{"type":"link","attrs":{"href":"/underwriting/contracts"}}]},{"type":"text","text":": identify the sponsor, dates, flights, placement quantities and any restrictions before activating an order."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"An eligible slot is not an obligation fulfilled"}]},{"type":"paragraph","content":[{"type":"text","text":"A contract may require a specified number of credits per week, on exact dates or within particular programs or inventory pools. Eligibility describes where a credit could air; demand describes what the signed order requires. Reconcile both when setting up the schedule. The "},{"type":"text","text":"Traffic dashboard","marks":[{"type":"link","attrs":{"href":"/underwriting"}}]},{"type":"text","text":" surfaces work needing attention."}]},{"type":"paragraph","content":[{"type":"text","text":"A credit also needs approved, eligible copy. The "},{"type":"text","text":"Copy library","marks":[{"type":"link","attrs":{"href":"/underwriting/copy"}}]},{"type":"text","text":" manages scripts and DAD cut references. Approval allows copy to be scheduled; a correct, recorded DAD cut is additionally necessary for unattended playback. Rotation weights determine how approved messages are distributed, but must respect line-specific copy restrictions."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Scheduled is not the same as aired"}]},{"type":"paragraph","content":[{"type":"text","text":"Check fulfillment against broadcast evidence, not just the number of placed credits. Handle misses and preemptions under "},{"type":"text","text":"Exceptions","marks":[{"type":"link","attrs":{"href":"/underwriting/exceptions"}}]},{"type":"text","text":", observing any agency-approval requirement for makegoods. Prepare "},{"type":"text","text":"Affidavits","marks":[{"type":"link","attrs":{"href":"/underwriting/affidavits"}}]},{"type":"text","text":" from reconciled activity. For automation exports, use On Air''s "},{"type":"text","text":"DAD log","marks":[{"type":"link","attrs":{"href":"/log/dad-log"}}]},{"type":"text","text":"; releasing a file does not itself confirm import or playout."}]},{"type":"paragraph","content":[{"type":"text","text":"Payment processing is separate from scheduling. For an approved card charge, use the station procedure "},{"type":"text","text":"Process an underwriter card payment","marks":[{"type":"link","attrs":{"href":"/resources/procedures/process-an-underwriter-card-payment"}}]},{"type":"text","text":"."}]}]}'::jsonb,version_note='Reconciled role-oriented overview; removed duplicate click-by-click instructions' where slug='traffic-workflow-overview' and kind='guide' and edited_since_release=false;
update public.rc_articles set title='On Air: producing, hosting and automation',summary='How this tool works, with contextual links to its detailed guidance.',body='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On Air connects the station''s program schedule and clocks with daily rundowns, locally produced content and automation exports. A host begins on "},{"type":"text","text":"Today","marks":[{"type":"link","attrs":{"href":"/log"}}]},{"type":"text","text":"; a producer also maintains reusable scripts and metadata in the "},{"type":"text","text":"Content library","marks":[{"type":"link","attrs":{"href":"/log/library"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"One schedule, different responsibilities"}]},{"type":"paragraph","content":[{"type":"text","text":"The program clock defines the available breaks and fixed elements. "},{"type":"text","text":"Programs","marks":[{"type":"link","attrs":{"href":"/log/programs"}}]},{"type":"text","text":" determines what airs when; "},{"type":"text","text":"Sources","marks":[{"type":"link","attrs":{"href":"/log/sources"}}]},{"type":"text","text":" shows imported NPR and weather information that should be checked for freshness before use. Producers review a rundown''s timing and required content; hosts execute it and report deviations."}]},{"type":"paragraph","content":[{"type":"text","text":"Operations defines unattended periods under "},{"type":"text","text":"Automation","marks":[{"type":"link","attrs":{"href":"/log/automated-hours"}}]},{"type":"text","text":" and controls which periods can accept underwriting under "},{"type":"text","text":"Underwriting hours","marks":[{"type":"link","attrs":{"href":"/log/underwriting-hours"}}]},{"type":"text","text":". Those settings are related but not interchangeable: an unattended hour is not necessarily open to credits."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Export, import and broadcast are distinct"}]},{"type":"paragraph","content":[{"type":"text","text":"Traffic reviews and releases the "},{"type":"text","text":"DAD log","marks":[{"type":"link","attrs":{"href":"/log/dad-log"}}]},{"type":"text","text":" for unattended hours after resolving missing or unrecorded cuts, ineligible copy and timing blockers. The export must then be imported into DAD, and actual playout checked through the station''s operational process. A change after release may require a new version."}]},{"type":"paragraph","content":[{"type":"text","text":"For equipment or transmission failure, do not improvise a recovery procedure from the scheduling tool. Use "},{"type":"text","text":"Restart broadcast systems after a total power failure","marks":[{"type":"link","attrs":{"href":"/resources/procedures/restart-after-a-total-power-failure"}}]},{"type":"text","text":" or the applicable Operations and Technology SOP."}]}]}'::jsonb,version_note='Reconciled role-oriented overview; removed duplicate click-by-click instructions' where slug='on-air-workflow-overview' and kind='guide' and edited_since_release=false;
update public.rc_articles set title='Sourcework: organizing and verifying evidence',summary='How this tool works, with contextual links to its detailed guidance.',body='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework keeps related reporting material together without treating the transcript as a substitute for the original recording or document. Open "},{"type":"text","text":"Projects","marks":[{"type":"link","attrs":{"href":"/sourcework"}}]},{"type":"text","text":" to start or continue a reporting workspace; use the "},{"type":"text","text":"Source Library","marks":[{"type":"link","attrs":{"href":"/sourcework?tab=sources"}}]},{"type":"text","text":" to locate material already in the system."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Know what each object represents"}]},{"type":"paragraph","content":[{"type":"text","text":"A source is the underlying audio or document. A transcript is derived text; an excerpt is a selected portion for reuse. Link a relevant existing source to another project where supported, instead of making an unnecessary duplicate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Check before quoting"}]},{"type":"paragraph","content":[{"type":"text","text":"Transcription and search accelerate reporting, but names, numbers, quotations, attribution and context should be verified against the original source whenever they matter. Search relevance is not independent evidence of accuracy. Preserve enough context with an excerpt for a colleague to understand who said what and in response to which question."}]},{"type":"paragraph","content":[{"type":"text","text":"The detailed project, transcript, excerpt and search guides explain the specific controls. Apply newsroom editorial and confidentiality requirements when handling sensitive material."}]}]}'::jsonb,version_note='Reconciled role-oriented overview; removed duplicate click-by-click instructions' where slug='sourcework-workflow-overview' and kind='guide' and edited_since_release=false;
update public.rc_articles set title='Editorial Planning: from idea to assignment',summary='How this tool works, with contextual links to its detailed guidance.',body='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Editorial Planning makes potential stories visible to the newsroom and records the decisions made about them. In the "},{"type":"text","text":"Pitch backlog","marks":[{"type":"link","attrs":{"href":"/editorial"}}]},{"type":"text","text":", explain the public question, who is affected, what evidence can address it, and why the reporting matters now."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Scores inform, but do not replace, editorial judgment"}]},{"type":"paragraph","content":[{"type":"text","text":"A coverage pillar identifies the substantive issue a pitch would illuminate. A university or institutional connection may be relevant, but it does not substitute for civic significance, verification or feasibility. The "},{"type":"text","text":"Settings","marks":[{"type":"link","attrs":{"href":"/editorial/settings"}}]},{"type":"text","text":" screens hold the pitch form and scoring rubric."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Make the decision actionable"}]},{"type":"paragraph","content":[{"type":"text","text":"In "},{"type":"text","text":"Planning meetings","marks":[{"type":"link","attrs":{"href":"/editorial/meetings"}}]},{"type":"text","text":", reviewers assess pitches and editors record a disposition. When assigning a pitch, clarify the reporting question, the next sources or evidence to pursue, the responsible reporter and the next editorial checkpoint. A ranking alone is not an assignment."}]},{"type":"paragraph","content":[{"type":"text","text":"Incoming messages from the shared newsroom address are managed separately; see "},{"type":"text","text":"Managing News Leads in Gmail","marks":[{"type":"link","attrs":{"href":"/resources/procedures/newsroom-gmail-news-leads"}}]},{"type":"text","text":"."}]}]}'::jsonb,version_note='Reconciled role-oriented overview; removed duplicate click-by-click instructions' where slug='editorial-planning-workflow-overview' and kind='guide' and edited_since_release=false;
update public.rc_articles set title='Audience Listening: from questions to reporting',summary='How this tool works, with contextual links to its detailed guidance.',body='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Audience Listening collects people''s experiences and questions to inform reporting. Start in "},{"type":"text","text":"Queries","marks":[{"type":"link","attrs":{"href":"/audience-listening"}}]},{"type":"text","text":" with a specific editorial uncertainty, and ask open-ended questions that do not assume an answer."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Participation and permission are not interchangeable"}]},{"type":"paragraph","content":[{"type":"text","text":"Before publication, review the query''s participant-information settings, consent language and attribution choices. Permission to contact someone is not the same as permission to name them; requests for anonymity must be handled according to the submitted record. Preview the participant experience before opening responses."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Treat responses as reporting leads"}]},{"type":"paragraph","content":[{"type":"text","text":"Listen to submissions, consider whether a response merits follow-up, and send relevant audio into Sourcework using the supported handoff. Preserve the original question and consent context when further reporting begins."}]},{"type":"paragraph","content":[{"type":"text","text":"An open-response listening query is not a representative poll. Recurring accounts can identify reporting questions, but response counts alone do not establish how common an experience is in the broader population. Corroborate consequential claims before publication."}]}]}'::jsonb,version_note='Reconciled role-oriented overview; removed duplicate click-by-click instructions' where slug='audience-listening-workflow-overview' and kind='guide' and edited_since_release=false;
update public.rc_articles set title='Roadmap: requests and decisions',summary='How this tool works, with contextual links to its detailed guidance.',body='{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Roadmap board","marks":[{"type":"link","attrs":{"href":"/roadmap"}}]},{"type":"text","text":" gathers product problems and proposed improvements. A useful request identifies who is affected, what happens today, why it matters, and what a successful change would make possible. Start from "},{"type":"text","text":"New request","marks":[{"type":"link","attrs":{"href":"/roadmap/new"}}]},{"type":"text","text":" when an existing item does not already capture the need."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A request is not a delivery commitment"}]},{"type":"paragraph","content":[{"type":"text","text":"Curators clarify and group requests, consider priority and feasibility, and move them through the board''s documented statuses. Comments should add evidence, reproduce a problem or describe a distinct use case rather than simply restate support."}]},{"type":"paragraph","content":[{"type":"text","text":"When a change is delivered, connect its release note and updated tool guide to the original request. Users should rely on the current board status and release documentation—not infer a ship date from an idea appearing on the roadmap."}]}]}'::jsonb,version_note='Reconciled role-oriented overview; removed duplicate click-by-click instructions' where slug='roadmap-workflow-overview' and kind='guide' and edited_since_release=false;
